  "signal_basis": {
    "component_id": "C057.signal_basis",
    "value": "Following a concurrency reduction held constant, observed output trajectories appear to reach a sustained range rather than keep drifting, with arrivals, workload mix, and resource conditions recorded alongside them.",
    "scope": "Assumed occurrence of the proposed response measurements; interpreting apparent settling also requires adequate observation time.",
